116	/// Strips source-context lines from raw compiler stderr so that file contents are
117	/// not echoed back to the caller.  Used for the non-JSON (exit-code != 0) error path.
118	pub(crate) fn sanitize_compiler_stderr(stderr: &str) -> String {
119	    stderr
120	        .lines()
121	        .filter(|line| !line.contains(" --> ") && !line.trim_start().starts_with('|'))
122	        .collect::<Vec<_>>()
123	        .join("\n")
124	}
